// Auth + input validation for every route. Anything that reaches a Supabase
// URL below has been checked here first — job ids especially, since they
// are interpolated into PostgREST filters.
const cfg = $('Config').first().json;
const req = $('Webhook').first().json;
const body = req.body && typeof req.body === 'object' ? req.body : {};
const fail = (code, error) => [{ json: { action: 'error', code, body: { ok: false, error } } }];

if (!cfg.dashboard_key || cfg.dashboard_key === 'CHANGE_ME') {
  return fail(500, 'Set dashboard_key in the Config node of workflow 10 first');
}
if (body.key !== cfg.dashboard_key) return fail(401, 'Wrong dashboard key');

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const action = String(body.action || '');

if (action === 'status') return [{ json: { action } }];

if (action === 'job' || action === 'retry') {
  const jobId = String(body.job_id || '');
  if (!UUID.test(jobId)) return fail(400, 'job_id must be a UUID');
  const from = String(body.from || 'auto');
  const FROM = ['auto', 'script', 'voice', 'images', 'video', 'render', 'deliver'];
  if (action === 'retry' && !FROM.includes(from)) {
    return fail(400, 'from must be one of: ' + FROM.join(', '));
  }
  return [{ json: { action, job_id: jobId.toLowerCase(), from } }];
}

if (action === 'topic') {
  const topic = String(body.topic || '').trim();
  if (topic.length < 3 || topic.length > 500) return fail(400, 'Topic must be 3-500 characters');
  return [{ json: { action, topic } }];
}

return fail(400, 'Unknown action: ' + action);

// alwaysOutputData turns an empty table into one empty item, so filter on id.
const rows = name => $(name).all().map(i => i.json).filter(r => r && r.id);
const num = v => (v == null ? null : Number(v));

const progress = Object.fromEntries(rows('Get Scene Progress').map(r => [r.id, r]));
const jobs = rows('Get Jobs').map(j => {
  const p = progress[j.id] || {};
  return {
    ...j,
    cost_usd:          num(j.cost_usd) || 0,
    scenes_total:      num(p.scenes_total) || 0,
    scenes_with_audio: num(p.scenes_with_audio) || 0,
    scenes_with_image: num(p.scenes_with_image) || 0,
    scenes_with_clip:  num(p.scenes_with_clip) || 0,
    est_duration_sec:  num(p.est_duration_sec)
  };
});

return [{ json: { code: 200, body: {
  ok: true,
  generated_at: new Date().toISOString(),
  jobs,
  topics: rows('Get Topics')
} } }];

const rows = name => $(name).all().map(i => i.json).filter(r => r && r.id);
const job = rows('Get Job')[0];
if (!job) return [{ json: { code: 404, body: { ok: false, error: 'Job not found' } } }];
const scenes = rows('Get Scenes');

// Same rule as Plan Retry: the first stage whose output is missing.
const all = f => scenes.length > 0 && scenes.every(f);
let suggested = null;
if (!job.script || scenes.length === 0) suggested = 'script';
else if (!all(s => s.audio_url && s.audio_duration_sec)) suggested = 'voice';
else if (!all(s => s.image_url)) suggested = 'images';
else if (job.use_video_gen && !all(s => s.clip_url)) suggested = 'video';
else if (!job.final_video_url) suggested = 'render';
else if (!job.drive_link) suggested = 'deliver';

return [{ json: { code: 200, body: {
  ok: true,
  job,
  scenes,
  events: rows('Get Events'),
  suggested_from: suggested
} } }];

// Replay = set the job back to the status the chosen stage claims from.
// Every stage skips work already done, so this only regenerates what is
// missing (README: Operating it) — except 'script', which replaces scenes.
const req = $('Validate Request').first().json;
const rows = name => $(name).all().map(i => i.json).filter(r => r && r.id);
const job = rows('Get Job For Retry')[0];
const scenes = rows('Get Scenes For Retry');
const out = (code, body, extra = {}) => [{ json: { code, body, ...extra } }];

if (!job) return out(404, { ok: false, error: 'Job not found' });

// Never yank a job out from under a running worker.
const BUSY = ['scripting', 'voicing', 'imaging', 'animating', 'editing', 'uploading'];
if (BUSY.includes(job.status)) {
  return out(409, { ok: false, error: 'Job is being worked on right now (' + job.status + '). Wait for it to finish, or for the sweeper to reset it.' });
}

const STATUS_FOR = {
  script:  'idea_ready',
  voice:   'script_ready',
  images:  'voice_ready',
  video:   'images_ready',
  render:  'clips_ready',
  deliver: 'render_ready'
};

let from = req.from;
if (from === 'auto') {
  const all = f => scenes.length > 0 && scenes.every(f);
  if (!job.script || scenes.length === 0) from = 'script';
  else if (!all(s => s.audio_url && s.audio_duration_sec)) from = 'voice';
  else if (!all(s => s.image_url)) from = 'images';
  else if (job.use_video_gen && !all(s => s.clip_url)) from = 'video';
  else if (!job.final_video_url) from = 'render';
  else if (!job.drive_link) from = 'deliver';
  else return out(409, { ok: false, error: 'Nothing is missing — this job is complete. Pick a stage explicitly to re-run it.' });
}

if (from === 'video' && !job.use_video_gen) {
  return out(400, { ok: false, error: 'Video generation is off for this job, so there is no video stage to re-run. Use render instead.' });
}

return out(200, null, {
  job_id: job.id,
  prev_status: job.status,
  from,
  patch: {
    status: STATUS_FOR[from],
    attempts: 0,
    claimed_at: null,
    last_error: null,
    status_changed_at: new Date().toISOString()
  }
});

const plan = $('Plan Retry').first().json;
const updated = $input.all().map(i => i.json).filter(r => r && r.id);
if (!updated.length) {
  return [{ json: { code: 409, body: { ok: false, error: 'The job changed while you were retrying it. Refresh and try again.' } } }];
}
return [{ json: { code: 200, body: {
  ok: true,
  job_id: plan.job_id,
  from: plan.from,
  status: plan.patch.status,
  message: 'Queued from ' + plan.from + ': ' + plan.prev_status + ' → ' + plan.patch.status
} } }];
